function debounce<T extends (...args: any[]) => void>(
  fn: T,
  ms: number,
  opts?: { leading?: boolean }
): T & { cancel(): void } {
  let timer: ReturnType<typeof setTimeout> | null = null;
  let inCooldown = false;

  const debounced = function (
    this: ThisParameterType<T>,
    ...args: Parameters<T>
  ): void {
    const leading = opts?.leading ?? false;

    if (leading) {
      // Fire immediately on the first call in a window.
      if (!inCooldown) {
        inCooldown = true;
        fn.apply(this, args);
      }

      // Restart the cooldown window; subsequent calls are suppressed.
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => {
        timer = null;
        inCooldown = false;
      }, ms);
    } else {
      // Trailing-edge: invoke with the latest args after the wait.
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => {
        timer = null;
        fn.apply(this, args);
      }, ms);
    }
  } as T & { cancel(): void };

  debounced.cancel = () => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
    inCooldown = false;
  };

  return debounced;
}
```

