```typescript
function debounce<T extends (...args: any[]) => void>(
  fn: T,
  ms: number,
  opts?: { leading?: boolean }
): T & { cancel(): void } {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const leading = opts?.leading ?? false;

  function debounced(this: any, ...args: Parameters<T>): void {
    if (leading) {
      // Leading edge: call immediately if there is no pending timer.
      if (!timer) {
        fn.apply(this, args);
        // Start the window; after ms the state resets.
        timer = setTimeout(() => {
          timer = undefined;
        }, ms);
      }
      // Subsequent calls within the window are suppressed.
    } else {
      // Trailing edge (default): reset the timer on each call.
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => {
        fn.apply(this, args);
        timer = undefined;
      }, ms);
    }
  }

  // Public method to cancel any pending invocation.
  debounced.cancel = () => {
    if (timer) clearTimeout(timer);
    timer = undefined;
  };

  return debounced as T & { cancel(): void };
}
