function parseDuration(s: string): number | null {
  // Optional h, optional m, optional s — but must stay in h→m→s order.
  // Each unit may appear at most once, values must be non‑negative integers.
  const match = s.match(/^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/);

  if (!match) return null;

  // Reject the empty string, which would otherwise match all-optional groups.
  if (match[1] === undefined && match[2] === undefined && match[3] === undefined) {
    return null;
  }

  const h = parseInt(match[1] ?? '0', 10);
  const m = parseInt(match[2] ?? '0', 10);
  const sec = parseInt(match[3] ?? '0', 10);

  return h * 3600 + m * 60 + sec;
}

/* ---------- Test cases ---------- */

function test(input: string, expected: number | null) {
  const got = parseDuration(input);
  const pass = got === expected;
  console.log(`${pass ? '✓' : '✗'} parseDuration("${input}") => ${got} (expected ${expected})`);
}

// Valid cases
test('1h30m15s', 5415);   // 1*3600 + 30*60 + 15
test('45m', 2700);
test('90s', 90);
test('2h', 7200);
test('1h60m', 4200);      // valid per the stated rules
test('0h0m0s', 0);        // all-zero unit values are allowed
test('0s', 0);            // zero with a unit is allowed

// Invalid cases
test('', null);           // no unit
test('1m1h', null);       // wrong order
test('1.5h', null);       // not an integer
test('h', null);          // missing value
test('10', null);         // missing unit
test('1h30m15s5s', null); // 's' appears twice
